import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
)

type Image struct {
	Data     []byte
	Mimetype string
}

var images = map[string]Image{}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		fh, header, _ := r.FormFile("image")
		defer fh.Close()
		data, _ := io.ReadAll(fh)
		images[header.Filename] = Image{Data: data, Mimetype: header.Header.Get("Content-Type")}
		json.NewEncoder(w).Encode(map[string]interface{}{"name": header.Filename, "size": len(data), "type": header.Header.Get("Content-Type")})
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}

