    data = await image.read()
    if width:
        img = Image.open(io.BytesIO(data))
        ratio = width / img.width
        new_h = int(img.height * ratio)
        img = img.resize((width, new_h))
        buf = io.BytesIO()
        img.save(buf, format=img.format or 'PNG')
        data = buf.getvalue()
    images[image.filename] = {'data': data, 'mimetype': image.content_type}
    return {'name': image.filename, 'size': len(data), 'type': image.content_type}
