package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"image"
	"image/jpeg"
	"image/png"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"

	"golang.org/x/image/draw"
)

type Image struct {
	Data     []byte
	Mimetype string
}
var images = map[string]Image{}

func resize(data []byte, width int, mimetype string) []byte {
	src, _, _ := image.Decode(bytes.NewReader(data))
	ratio := float64(width) / float64(src.Bounds().Dx())
	nh := int(float64(src.Bounds().Dy()) * ratio)
	dst := image.NewRGBA(image.Rect(0, 0, width, nh))
	draw.NearestNeighbor.Scale(dst, dst.Bounds(), src, src.Bounds(), draw.Over, nil)
	var buf bytes.Buffer
	if strings.Contains(mimetype, "png") { png.Encode(&buf, dst) } else { jpeg.Encode(&buf, dst, nil) }
	return buf.Bytes()
}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		fh, header, _ := r.FormFile("image")
		defer fh.Close()
		data, _ := io.ReadAll(fh)
		if wStr := r.URL.Query().Get("width"); wStr != "" {
			w, _ := strconv.Atoi(wStr)
			data = resize(data, w, header.Header.Get("Content-Type"))
		}
		images[header.Filename] = Image{Data: data, Mimetype: header.Header.Get("Content-Type")}
		json.NewEncoder(w).Encode(map[string]interface{}{"name": header.Filename, "size": len(data), "type": header.Header.Get("Content-Type")})
	})

	http.HandleFunc("/images/", func(w http.ResponseWriter, r *http.Request) {
		name := strings.TrimPrefix(r.URL.Path, "/images/")
		if strings.HasSuffix(name, "/thumbnail") { return }
		img, ok := images[name]
		if !ok { w.WriteHeader(404); return }
		w.Header().Set("Content-Type", img.Mimetype)
		w.Write(img.Data)
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}

