        return Response(content=thumbs[name], media_type='image/jpeg')
    img = images.get(name)
    if not img: return Response(status_code=404)
    thumb = make_thumb(img['data'], 200)
    thumbs[name] = thumb
    return Response(content=thumb, media_type='image/jpeg')
